def _strip_grouping_chars(s):
    """Strip grouping characters (commas and underscores) from a number string."""
    return s.replace(',', '').replace('_', '')


class DecimalWithGrouping(float):
    """A converter that handles decimal strings with grouping characters."""
    def __new__(cls, value):
        return super().__new__(cls, _strip_grouping_chars(value))


def convert_decimal_with_grouping(string, match):
    """Convert a string to float, stripping grouping characters."""
    return float(_strip_grouping_chars(string))


def convert_decimal_with_grouping_decimal(string, match):
    """Convert a string to Decimal, stripping grouping characters."""
    return Decimal(_strip_grouping_chars(string))
